// Package auth is login, register, status, profile and logout, ported from
// the_deno's AuthController template, on the app's "user", "active_role" and
// "role" models (generated by compile-php).
//
// Routes() gives the same paths as the Deno template's Routes/Auth.ts:
//
//	GET  /login     who is logged in (401 when nobody)
//	POST /login     {email, password}
//	POST /register  {name, email, password}
//	GET  /logout
//	GET  /profile   the user's row, without the password
package auth

import (
	"crypto/subtle"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"net/http"
	"strings"

	"golang.org/x/crypto/bcrypt"
	"golang.org/x/crypto/sha3"

	"github.com/puneetxp/the_go/model"
	"github.com/puneetxp/the_go/router"
	"github.com/puneetxp/the_go/session"
)

// Model names the handlers look up with model.Lookup.
var (
	UserModel       = "user"
	ActiveRoleModel = "active_role"
	RoleModel       = "role"
)

// Routes are the auth routes, to add to the app's route list.
func Routes() []router.Route {
	return []router.Route{
		{Path: "/login", Method: "GET", Handler: Status, Islogin: true},
		{Path: "/login", Method: "POST", Handler: Login},
		{Path: "/register", Method: "POST", Handler: Register},
		{Path: "/logout", Method: "GET", Handler: Logout, Islogin: true},
		{Path: "/profile", Method: "GET", Handler: Profile, Islogin: true},
	}
}

// Password hashing shared by every adapter (spec/auth_cases.json): bcrypt,
// cost 10. Hashes from the Deno, PHP and Go adapters verify in each other.
const (
	Cost     = 10
	MaxBytes = 72 // bcrypt reads only the first 72 bytes; longer is refused
)

// ErrTooLong: the password is over MaxBytes.
var ErrTooLong = fmt.Errorf("Password must be at most %d bytes", MaxBytes)

// Hash is the bcrypt hash to store for password.
func Hash(password string) (string, error) {
	if len(password) > MaxBytes {
		return "", ErrTooLong
	}
	h, err := bcrypt.GenerateFromPassword([]byte(password), Cost)
	return string(h), err
}

// Verify checks password against a stored hash. rehash says the hash should
// be replaced (an old unsalted SHA3-256, the_deno base64 or the_lib hex, or a
// bcrypt of another cost), which Login does once the password is known good.
func Verify(password, stored string) (ok, rehash bool) {
	if stored == "" {
		return false, false
	}
	if strings.HasPrefix(stored, "$2") {
		if bcrypt.CompareHashAndPassword([]byte(stored), []byte(password)) != nil {
			return false, false
		}
		cost, err := bcrypt.Cost([]byte(stored))
		return true, err != nil || cost != Cost
	}
	sum := sha3.Sum256([]byte(password))
	for _, want := range []string{base64.StdEncoding.EncodeToString(sum[:]), hex.EncodeToString(sum[:])} {
		if subtle.ConstantTimeCompare([]byte(want), []byte(stored)) == 1 {
			return true, true
		}
	}
	return false, false
}

func models() (user, activeRole, role *model.Model, err error) {
	user, activeRole, role = model.Lookup(UserModel), model.Lookup(ActiveRoleModel), model.Lookup(RoleModel)
	if user == nil || activeRole == nil || role == nil {
		err = fmt.Errorf("auth needs the %q, %q and %q models to be defined", UserModel, ActiveRoleModel, RoleModel)
	}
	return
}

// Roles are the role names given to a user through active_roles.
func Roles(c *router.Ctx, userID any) ([]string, error) {
	_, activeRole, role, err := models()
	if err != nil {
		return nil, err
	}
	links, err := activeRole.Where(model.W{"user_id": userID}).Get(c.Context())
	if err != nil {
		return nil, err
	}
	ids := make([]any, 0, len(links))
	for _, l := range links {
		ids = append(ids, l["role_id"])
	}
	rows, err := role.Where(model.W{"id": ids}).OrderBy("id", "ASC").Get(c.Context())
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(rows))
	for _, r := range rows {
		if n, ok := r["name"].(string); ok {
			names = append(names, n)
		}
	}
	return names, nil
}

func loginFor(c *router.Ctx, u model.Row) (session.Login, error) {
	roles, err := Roles(c, u["id"])
	if err != nil {
		return session.Login{}, err
	}
	id, _ := u["id"].(int64)
	name, _ := u["name"].(string)
	email, _ := u["email"].(string)
	return session.Login{ID: id, Name: name, Email: email, Roles: roles}, nil
}

type credentials struct {
	Name     string `json:"name"`
	Email    string `json:"email"`
	Password string `json:"password"`
}

// Status: who is logged in.
func Status(c *router.Ctx) error {
	return c.JSON(http.StatusOK, c.Login)
}

// Login checks email and password and starts a session.
func Login(c *router.Ctx) error {
	user, _, _, err := models()
	if err != nil {
		return err
	}
	var in credentials
	if err := c.Bind(&in); err != nil {
		return c.JSON(http.StatusUnprocessableEntity, "Email and password are required")
	}
	u, err := user.Find(c.Context(), strings.TrimSpace(in.Email), "email")
	if err != nil {
		return err
	}
	if u == nil {
		return c.JSON(http.StatusNotFound, "User Not Found")
	}
	if enable, ok := u["enable"].(int64); ok && enable == 0 {
		return c.JSON(http.StatusForbidden, "This account has been disabled")
	}
	stored, _ := u["password"].(string)
	ok, rehash := Verify(in.Password, stored)
	if !ok {
		return c.JSON(http.StatusUnauthorized, "Password is Incorrect")
	}
	if rehash {
		// An old SHA3 hash: store bcrypt now that the password is known.
		if h, err := Hash(in.Password); err == nil {
			if _, err := user.Where(model.W{"id": u["id"]}).Update(c.Context(), model.W{"password": h}); err != nil {
				return err
			}
		}
	}
	login, err := loginFor(c, u)
	if err != nil {
		return err
	}
	if err := c.StartSession(login); err != nil {
		return err
	}
	return c.JSON(http.StatusOK, c.Login)
}

// Register creates the user and starts a session.
func Register(c *router.Ctx) error {
	user, _, _, err := models()
	if err != nil {
		return err
	}
	var in credentials
	if err := c.Bind(&in); err != nil || strings.TrimSpace(in.Email) == "" || in.Password == "" {
		return c.JSON(http.StatusUnprocessableEntity, "Email and password are required")
	}
	email := strings.TrimSpace(in.Email)
	if existing, err := user.Find(c.Context(), email, "email"); err != nil {
		return err
	} else if existing != nil {
		return c.JSON(http.StatusUnprocessableEntity, map[string]string{"email": "Email Already Taken"})
	}
	hash, err := Hash(in.Password)
	if err == ErrTooLong {
		return c.JSON(http.StatusUnprocessableEntity, map[string]string{"password": err.Error()})
	} else if err != nil {
		return err
	}
	u, err := user.Create(c.Context(), model.W{"name": in.Name, "email": email, "password": hash})
	if err != nil {
		return err
	}
	login, err := loginFor(c, u)
	if err != nil {
		return err
	}
	if err := c.StartSession(login); err != nil {
		return err
	}
	return c.JSON(http.StatusOK, c.Login)
}

// Profile is the logged-in user's row, without the password.
func Profile(c *router.Ctx) error {
	user, _, _, err := models()
	if err != nil {
		return err
	}
	u, err := user.Find(c.Context(), c.Login.ID)
	if err != nil {
		return err
	}
	if u == nil {
		return c.JSON(http.StatusNotFound, "User Not Found")
	}
	delete(u, "password")
	return c.JSON(http.StatusOK, u)
}

// Logout ends the session.
func Logout(c *router.Ctx) error {
	if err := c.EndSession(); err != nil {
		return err
	}
	return c.JSON(http.StatusOK, map[string]string{"ok": "Logout"})
}
